rows["421:508040561"]="적을 개구리로 변형하여 최대 50 초 동안 돌아다니도록 강요합니다. 방랑하는 동안 개구리는 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 다시 변환합니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 짐승, 인간과 크리터에서만 작동합니다.\010\010사용 시 소비하지 않습니다. 마나폭풍에서만 사용할 수 있습니다.\010\010|cFF33FFF0마나폭풍 유틸리티|r"
rows["424:893066231"]="여러 유서품을 포함하는 캐시, 하지만 경험 증진을 제공하지 않습니다.\010마법사의 손가락 x1이 포함되어 있습니다\010시야의 손가락 x1을 포함하고 있습니다\010x1 미스틱 코트 오브 에리먼트\010x1 미스틱 벨트 오브 에리먼트가 포함되어 있습니다\010x1 미스틱  ⁇ 의 요소가 포함되어 있습니다\010x1 미스틱 브레이커의 요소가 포함되어 있습니다\010x1 미스틱 킬트 오브 에리먼트를 포함합니다\010x1 미스틱 헬멧의 요소가 포함되어 있습니다\010x1 미스틱 글래브의 요소가 포함되어 있습니다"
rows["427:737083688"]="여러 유서품을 포함하는 캐시, 하지만 경험 증진을 제공하지 않습니다.\010마법사의 손가락 x1이 포함되어 있습니다\010시야의 손가락 x1을 포함하고 있습니다\010x1  ⁇ 은 철 깃털의 담요\010x1  ⁇ 은 철발자 벨트\010x1  ⁇ 은 철발가락이 들어있어요\010x1  ⁇ 은 철개 브레이커가 들어있다\010x1  ⁇ 은 철발 다리보호가 포함되어 있습니다\010x1  ⁇ 은 철 깃발 머리 보호 장치\010x1  ⁇ 은 철수지갑이 포함되어 있습니다"
