rows["456:1076899138"]="< ⁇ 발한 손으로 쓴 서적의 문장>\010\010모르그웨나 어머니의 명령은 분명합니다. 우리는 나중에 귀족과 대결할 것입니다. 현재는 그의 야망을 이용해야 합니다. 다레네가르 우물과 연결되는 엘디히 동굴에 들어가, 당신이 가지고 갈 수있는 모든 무기를 가져가십시오. 그것은 스톰윈드 철입니다. 많은 사람들이 무엇을 생각하고 있는지 알고 있습니다. 그러나 이것을 이렇게 보세요: 우리는 그들의 칼로 우리의 적을 죽일 것입니다. 숲의 영은 웃음으로 울릴 것입니다."
rows["459:1663569279"]="|cff00ff00 항목을 혈액조작 동원형으로 변환|r\010|cffff0000\010피조기는 PvE 전력을 제거하고 PvP 전력으로 대체합니다.\010\010피가 왜곡된 영웅이나 승진한 공격에 참여하면, 당신은 피가 묻은 배반을 받을 것입니다. \010이것은 당신의 피해와 치유를 20%로 줄이고, 당신이 받는 피해를 20%로 증가시킬 것이다.\010\010조심해 영웅들, 이건 돌이킬 수 없는 일이야. |r"
